from auto_config.generator.vcu.managed_objects.managed_object import ManagedObject


class FeatcadmParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        self.set_parameter('actBbReconfigImprovement', 'false')
        self.set_parameter('actCli', 'true')
        self.set_parameter('actDualStackIpV4V6ForMplane', 'false')
        self.set_parameter('actEAPMode', 'EAP disabled')
        self.set_parameter('actHierarchyAutoFix', 'false')
        self.set_parameter('actL1ReconfigImprovement', 'false')
        self.set_parameter('actPimTesting', 'false')
        self.set_parameter('actPreservingRFPortMapp', 'false')
        self.set_parameter('actRxMonitoring', 'false')
        self.set_parameter('actSyncLinkSwitchover', 'false')
        if execution_config['release'] >= 25.1:
            self.set_parameter('cntrldResetMplaneBreakTime', '300')
            self.set_parameter('uncntrldResetMplaneBreakTime', '0')

        self.set_struct_parameter('preventParamModifList', [
            'FEATCADM-actLocInfoStore'
        ])
        if execution_config["is_fullrack"]:
            self.set_parameter('actSecCoreBackplaneReset', 'enableAll')
